import { defineConfig } from 'astro/config';
import site from './src/data/site.json' with { type: 'json' };

// Fully static output - no server, no backend. Upload `dist/` to any static host.
// Sitemap (/sitemap.xml), robots.txt and llms.txt are generated by endpoints in src/pages/.
export default defineConfig({
  site: site.siteUrl,
  output: 'static',
  trailingSlash: 'always',
  build: { format: 'directory' },
});
